#include <iostream>
#include <cstdio>
#include <cmath>
#include <cstring>
#include <algorithm>
using namespace std;

int n_input, k_input, mod_input;
long long factorials[250003], invs[250003];
long long cache_dp[27][250003];

int lowbit_value(int x) { return x & (-x); }

long long fast_pow_mod(long long base, int exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod_input;
        base = (base * base) % mod_input;
        exp >>= 1;
    }
    return res;
}

void prepare() {
    factorials[0] = 1;
    for (int i = 1; i <= n_input; ++i)
        factorials[i] = (factorials[i - 1] * i) % mod_input;
    invs[n_input] = fast_pow_mod(factorials[n_input], mod_input - 2);
    for (int i = n_input - 1; i >= 0; --i)
        invs[i] = (invs[i + 1] * (i + 1)) % mod_input;
}

long long compute(int x, int s) {
    if (cache_dp[x][s] != -1) return cache_dp[x][s];
    if (s == 0) return cache_dp[x][s] = (factorials[n_input] * factorials[k_input] % mod_input) * invs[k_input - x] % mod_input;
    int rem = s - lowbit_value(s);
    long long total_sum = 0;
    for (int t = rem; t; t = (t - 1) & rem)
        total_sum = (total_sum + compute(x + 1, t) * invs[s - t]) % mod_input;
    total_sum = (total_sum + compute(x + 1, 0) * invs[s]) % mod_input;
    return cache_dp[x][s] = total_sum;
}

int main() {
    scanf("%d %d %d", &n_input, &k_input, &mod_input);
    prepare();
    long long result = fast_pow_mod(k_input, n_input);
    if (n_input % 2 == 0) {
        memset(cache_dp, -1, sizeof(cache_dp));
        result = (result - compute(0, n_input) + mod_input) % mod_input;
    }
    printf("%lld", result);
    return 0;
}
